//! 📑️ Authored document blocks, typed collections, formatting, styles and images.
use crate::standards::v1::subsets::base::schema::snapshot::sqlite::native::Bound;
use semio_framework_os_kernel::sqlite_snapshot::artifact::{FloatColumn,FloatRow as SqliteRow,insert_ieee754,insert_key_ieee754};
use super::{SemioDocumentSnapshot,DocBlock,DocStyle,DocImage,DocRun,RunStyle,DocListItem,DocTableRow,DocTableCell};
use semio_framework_os_kernel::{ArtifactSqliteSnapshot,sqlite_snapshot::{artifact::{Cell,Projection,Reconstruction},validate_sqlite_database_schema,SqliteDatabase,SqliteValue,SqliteSnapshotControl,SqliteSnapshotPhase}};
use std::collections::{BTreeMap,BTreeSet};
/// 📚️ Explicit table names for the actual DocBlock types shared by document and presentation.
#[derive(Clone,Copy)]
pub struct DocSqliteTables{pub collection:&'static str,pub member:&'static str,pub block:&'static str,pub paragraph:&'static str,pub heading:&'static str,pub run:&'static str,pub list:&'static str,pub list_item:&'static str,pub table:&'static str,pub table_row:&'static str,pub table_cell:&'static str,pub code:&'static str,pub quote:&'static str,pub image_block:&'static str,pub page_break:&'static str}
/// 📑️ The document's independently declared block table names.
pub const DOCUMENT_TABLES:DocSqliteTables=DocSqliteTables{collection:"semio_document_collection",member:"semio_document_member",block:"semio_document_block",paragraph:"semio_document_paragraph",heading:"semio_document_heading",run:"semio_document_run",list:"semio_document_list",list_item:"semio_document_list_item",table:"semio_document_table",table_row:"semio_document_table_row",table_cell:"semio_document_table_cell",code:"semio_document_code",quote:"semio_document_quote",image_block:"semio_document_image_block",page_break:"semio_document_page_break"};
fn number(n:usize)->Result<i64,String>{i64::try_from(n).map_err(|e|e.to_string())}
fn identity<'a>(row:impl std::borrow::Borrow<SqliteRow<'a>>,n:usize)->Result<(),String>{let row=*row.borrow();if row.rowid<=0||row.integer(0)?!=row.rowid||row.values.len()!=n{Err("invalid document entity identity or columns".into())}else{Ok(())}}
fn boolean(n:i64)->Result<bool,String>{match n{0=>Ok(false),1=>Ok(true),_=>Err("invalid document boolean".into())}}
fn optional_real(row:SqliteRow<'_>,i:usize)->Result<Option<f64>,String>{if row.is_null(i)?{Ok(None)}else{row.real(i).map(Some)}}
fn optional_integer(row:SqliteRow<'_>,i:usize)->Result<Option<i64>,String>{if row.is_null(i)?{Ok(None)}else{row.integer(i).map(Some)}}
fn optional_text(row:SqliteRow<'_>,i:usize,r:&mut Reconstruction<'_,'_>)->Result<Option<String>,String>{row.optional_text(i)?.map(|s|r.text(s)).transpose()}
fn reference<'a>(native:Option<&'a str>,names:Option<&BTreeMap<&str,i64>>)->Result<Cell<'a>,String>{match native{None=>Ok(Cell::Null),Some(name)=>match names{Some(map)=>Ok(Cell::Integer(*map.get(name).ok_or("dangling document named reference")?)),None=>Ok(Cell::Text(name))}}}
fn restore_reference(row:SqliteRow<'_>,i:usize,names:Option<&BTreeMap<i64,&str>>,r:&mut Reconstruction<'_,'_>)->Result<Option<String>,String>{if row.is_null(i)?{return Ok(None);}let value=match names{Some(map)=>*map.get(&row.integer(i)?).ok_or("dangling document named reference")?,None=>row.text(i)?};r.text(value).map(Some)}
/// 🧱️ Projects only the explicitly shared native DocBlock tree with an iterative ownership walk.
pub fn project_block_collection(blocks:&[DocBlock],t:DocSqliteTables,styles:Option<&BTreeMap<&str,i64>>,images:Option<&BTreeMap<&str,i64>>,p:&mut Projection<'_,'_>)->Result<i64,String>{
let root=p.insert_float(t.collection,&[])?;let mut pending=vec![(root,blocks)];while let Some((collection,blocks))=pending.pop(){p.check_rows(blocks.len().checked_add(pending.len()).ok_or("document traversal count overflow")?)?;for(ordinal,block)in blocks.iter().enumerate(){let kind=match block{DocBlock::Paragraph{..}=>"paragraph",DocBlock::Heading{..}=>"heading",DocBlock::List{..}=>"list",DocBlock::Table{..}=>"table",DocBlock::Code{..}=>"code",DocBlock::Quote{..}=>"quote",DocBlock::Image{..}=>"image",DocBlock::PageBreak=>"pageBreak"};let id=p.insert_float(t.block,&[Cell::Text(kind)])?;p.insert_float(t.member,&[Cell::Integer(collection),Cell::Integer(number(ordinal)?),Cell::Integer(id)])?;
match block{
DocBlock::Paragraph{style_id,..}=>p.insert_key_float(t.paragraph,id,&[reference(style_id.as_deref(),styles)?])?,
DocBlock::Heading{level,style_id,..}=>p.insert_key_float(t.heading,id,&[Cell::Integer(i64::from(*level)),reference(style_id.as_deref(),styles)?])?,
DocBlock::List{ordered,items}=>{p.insert_key_float(t.list,id,&[Cell::Integer(i64::from(*ordered))])?;p.check_rows(pending.len().checked_add(items.len()).ok_or("document list traversal overflow")?)?;for(ordinal,item)in items.iter().enumerate(){let child=p.insert_float(t.collection,&[])?;p.insert_float(t.list_item,&[Cell::Integer(id),Cell::Integer(number(ordinal)?),Cell::Integer(child)])?;pending.push((child,item.blocks.as_slice()));}},
DocBlock::Table{rows}=>{p.insert_key_float(t.table,id,&[])?;for(ordinal,row)in rows.iter().enumerate(){let row_id=p.insert_float(t.table_row,&[Cell::Integer(id),Cell::Integer(number(ordinal)?)])?;p.check_rows(pending.len().checked_add(row.cells.len()).ok_or("document table traversal overflow")?)?;for(ordinal,cell)in row.cells.iter().enumerate(){let child=p.insert_float(t.collection,&[])?;p.insert_float(t.table_cell,&[Cell::Integer(row_id),Cell::Integer(number(ordinal)?),Cell::Integer(child)])?;pending.push((child,cell.blocks.as_slice()));}}},
DocBlock::Code{language,text}=>p.insert_key_float(t.code,id,&[language.as_deref().map(Cell::Text).unwrap_or(Cell::Null),Cell::Text(text)])?,
DocBlock::Quote{blocks}=>{let child=p.insert_float(t.collection,&[])?;p.insert_key_float(t.quote,id,&[Cell::Integer(child)])?;pending.push((child,blocks));},
DocBlock::Image{image_id,alt,width,height}=>p.insert_key_float(t.image_block,id,&[reference(Some(image_id),images)?,Cell::Text(alt),width.map(Cell::Real).unwrap_or(Cell::Null),height.map(Cell::Real).unwrap_or(Cell::Null)])?,
DocBlock::PageBreak=>p.insert_key_float(t.page_break,id,&[])?}
if let DocBlock::Paragraph{runs,..}|DocBlock::Heading{runs,..}=block{for(ordinal,run)in runs.iter().enumerate(){let s=&run.style;p.insert_float(t.run,&[Cell::Integer(id),Cell::Integer(number(ordinal)?),Cell::Text(&run.text),Cell::Integer(i64::from(s.bold)),Cell::Integer(i64::from(s.italic)),Cell::Integer(i64::from(s.underline)),s.size.map(Cell::Real).unwrap_or(Cell::Null),s.font.as_deref().map(Cell::Text).unwrap_or(Cell::Null),s.color.as_deref().map(Cell::Text).unwrap_or(Cell::Null),s.link.as_deref().map(Cell::Text).unwrap_or(Cell::Null)])?;}}p.checkpoint()?;}}
Ok(root)}
fn details<'a>(db:&'a SqliteDatabase,name:&str,columns:usize,control:&mut SqliteSnapshotControl<'_>)->Result<BTreeMap<i64,SqliteRow<'a>>,String>{let mut result=BTreeMap::new();for(n,row)in float_rows(db,name,control)?.into_iter().enumerate(){identity(row,columns)?;if result.insert(row.rowid,row).is_some(){return Err("duplicate document entity identity".into());}if n%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,n,0)?;}}Ok(result)}
fn groups<'a>(db:&'a SqliteDatabase,name:&str,columns:usize,parents:&BTreeMap<i64,SqliteRow<'_>>,control:&mut SqliteSnapshotControl<'_>)->Result<BTreeMap<i64,Vec<SqliteRow<'a>>>,String>{let mut result=BTreeMap::<i64,Vec<SqliteRow<'_>>>::new();let mut ids=BTreeSet::new();for(n,row)in float_rows(db,name,control)?.into_iter().enumerate(){identity(row,columns)?;if !ids.insert(row.rowid)||!parents.contains_key(&row.integer(1)?){return Err("invalid document relationship owner or identity".into());}row.integer(2)?;result.entry(row.integer(1)?).or_default().push(row);if n%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,n,0)?;}}for rows in result.values_mut(){rows.sort_by_key(|row|row.integer(2).unwrap_or(-1));for(ordinal,row)in rows.iter().enumerate(){if row.integer(2)?!=number(ordinal)?{return Err("document relationship order must be contiguous".into());}}}Ok(result)}
/// 🧩️ Reconstructs actual DocBlock fields, rejecting cycles, aliases, dangling relationships and variant contradictions.
pub fn reconstruct_block_collections(db:&SqliteDatabase,t:DocSqliteTables,roots:&[i64],styles:Option<&BTreeMap<i64,&str>>,images:Option<&BTreeMap<i64,&str>>,control:&mut SqliteSnapshotControl<'_>)->Result<Vec<Vec<DocBlock>>,String>{
let collections=details(db,t.collection,1,control)?;let mut blocks=details(db,t.block,2,control)?;let members=groups(db,t.member,4,&collections,control)?;
let mut paragraphs=details(db,t.paragraph,2,control)?;let mut headings=details(db,t.heading,3,control)?;let mut lists=details(db,t.list,2,control)?;let mut tables=details(db,t.table,1,control)?;let mut codes=details(db,t.code,3,control)?;let mut quotes=details(db,t.quote,2,control)?;let mut image_blocks=details(db,t.image_block,5,control)?;let mut page_breaks=details(db,t.page_break,1,control)?;
let mut run_parents=paragraphs.clone();for(id,row)in &headings{if run_parents.insert(*id,*row).is_some(){return Err("contradictory paragraph and heading fields".into());}}let mut runs=groups(db,t.run,11,&run_parents,control)?;let mut items=groups(db,t.list_item,4,&lists,control)?;let mut rows=groups(db,t.table_row,3,&tables,control)?;let table_rows=details(db,t.table_row,3,control)?;let mut cells=groups(db,t.table_cell,4,&table_rows,control)?;
let mut visited_collections=BTreeSet::new();let mut visited_blocks=BTreeSet::new();let mut schedule=Vec::new();let mut stack:Vec<(i64,bool)>=roots.iter().rev().map(|id|(*id,false)).collect();while let Some((id,done))=stack.pop(){if done{schedule.push(id);continue;}if !collections.contains_key(&id)||!visited_collections.insert(id){return Err("cyclic, multiply owned or dangling document block collection".into());}stack.push((id,true));for member in members.get(&id).into_iter().flatten(){let block_id=member.integer(3)?;let block=blocks.get(&block_id).ok_or("dangling document block member")?;if !visited_blocks.insert(block_id){return Err("multiply owned document block".into());}match block.text(1)?{
"list"=>for row in items.get(&block_id).into_iter().flatten(){stack.push((row.integer(3)?,false));},
"table"=>for row in rows.get(&block_id).into_iter().flatten(){for cell in cells.get(&row.rowid).into_iter().flatten(){stack.push((cell.integer(3)?,false));}},
"quote"=>stack.push((quotes.get(&block_id).ok_or("missing quote fields")?.integer(1)?,false)),_=>{}}}if visited_collections.len()%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,visited_collections.len(),0)?;}}
if visited_collections.len()!=collections.len()||visited_blocks.len()!=blocks.len(){return Err("orphan document block or collection".into());}let mut restore=Reconstruction::new(control)?;let mut built=BTreeMap::<i64,Vec<DocBlock>>::new();for collection in schedule{let mut native=Vec::new();for member in members.get(&collection).into_iter().flatten(){let id=member.integer(3)?;let row=blocks.remove(&id).ok_or("duplicate document block ownership")?;let block=match row.text(1)?{
"paragraph"|"heading"=>{let mut native_runs=Vec::new();for run in runs.remove(&id).unwrap_or_default(){native_runs.push(DocRun{text:restore.text(run.text(3)?)?,style:RunStyle{bold:boolean(run.integer(4)?)?,italic:boolean(run.integer(5)?)?,underline:boolean(run.integer(6)?)?,size:optional_real(run,7)?,font:optional_text(run,8,&mut restore)?,color:optional_text(run,9,&mut restore)?,link:optional_text(run,10,&mut restore)?}});}if row.text(1)?=="paragraph"{let r=paragraphs.remove(&id).ok_or("missing paragraph fields")?;DocBlock::Paragraph{style_id:restore_reference(r,1,styles,&mut restore)?,runs:native_runs}}else{let r=headings.remove(&id).ok_or("missing heading fields")?;DocBlock::Heading{level:u8::try_from(r.integer(1)?).map_err(|e|e.to_string())?,style_id:restore_reference(r,2,styles,&mut restore)?,runs:native_runs}}},
"list"=>{let r=lists.remove(&id).ok_or("missing list fields")?;let mut native_items=Vec::new();for item in items.remove(&id).unwrap_or_default(){native_items.push(DocListItem{blocks:built.remove(&item.integer(3)?).ok_or("missing owned list block collection")?});}DocBlock::List{ordered:boolean(r.integer(1)?)?,items:native_items}},
"table"=>{tables.remove(&id).ok_or("missing table fields")?;let mut native_rows=Vec::new();for row in rows.remove(&id).unwrap_or_default(){let mut native_cells=Vec::new();for cell in cells.remove(&row.rowid).unwrap_or_default(){native_cells.push(DocTableCell{blocks:built.remove(&cell.integer(3)?).ok_or("missing owned table cell collection")?});}native_rows.push(DocTableRow{cells:native_cells});}DocBlock::Table{rows:native_rows}},
"code"=>{let r=codes.remove(&id).ok_or("missing code fields")?;DocBlock::Code{language:optional_text(r,1,&mut restore)?,text:restore.text(r.text(2)?)?}},
"quote"=>{let r=quotes.remove(&id).ok_or("missing quote fields")?;DocBlock::Quote{blocks:built.remove(&r.integer(1)?).ok_or("missing owned quote collection")?}},
"image"=>{let r=image_blocks.remove(&id).ok_or("missing image block fields")?;DocBlock::Image{image_id:restore_reference(r,1,images,&mut restore)?.ok_or("null document image reference")?,alt:restore.text(r.text(2)?)?,width:optional_real(r,3)?,height:optional_real(r,4)?}},
"pageBreak"=>{page_breaks.remove(&id).ok_or("missing page break fields")?;DocBlock::PageBreak},_=>return Err("unknown document block kind".into())};native.push(block);restore.checkpoint()?;}built.insert(collection,native);}
if !paragraphs.is_empty()||!headings.is_empty()||!lists.is_empty()||!tables.is_empty()||!codes.is_empty()||!quotes.is_empty()||!image_blocks.is_empty()||!page_breaks.is_empty()||!runs.is_empty()||!items.is_empty()||!rows.is_empty()||!cells.is_empty(){return Err("orphan or contradictory document block detail".into());}let mut result=Vec::new();for root in roots{result.push(built.remove(root).ok_or("missing root block collection")?);}if !built.is_empty(){return Err("orphan native block collection".into());}restore.checkpoint()?;Ok(result)}
fn style_cycles(parents:&BTreeMap<i64,Option<i64>>,control:&mut SqliteSnapshotControl<'_>)->Result<(),String>{let mut done=BTreeSet::new();for start in parents.keys(){let mut path=BTreeSet::new();let mut current=Some(*start);while let Some(id)=current{if done.contains(&id){break;}if !path.insert(id){return Err("cyclic document style inheritance".into());}current=*parents.get(&id).ok_or("dangling document style inheritance")?;if path.len()%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,path.len(),0)?;}}done.extend(path);}Ok(())}
impl ArtifactSqliteSnapshot for SemioDocumentSnapshot{
fn preflight_sqlite_snapshot_encoding(&self,_encoding:semio_framework_os_kernel::sqlite_snapshot::SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<(),String>{let mut b=Bound::new("",control)?;self.native_fields(&mut b)?;b.finish()}

fn validate_sqlite_snapshot_subset(&self,dialect:&store::os_io::ArtifactDialect,database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>)->semio_framework_os_kernel::io_schema::IoResult<()>{
control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,0,1)?;
if dialect.artifact_kind!="s.stdio.semio"||dialect.standard!="v1"||(dialect.subset!="*"&&dialect.subset!="document"){return Err(String::from("Semio owned snapshot dialect differs from its dedicated semantic subset").into());}
let row=database.table("semio_document_document")?.single_row()?;
if row.rowid!=1||row.integer(0)?!=1||row.text(1)?!=self.schema{return Err(String::from("Semio owned document identity differs from projected semantic fields").into());}
control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,1,1)?;Ok(semio_framework_os_kernel::io_schema::IoOutcome::clean(()))}

const SQLITE_SCHEMA:&'static str=include_str!("🗄️.sql");
fn to_sqlite_database(&self,control:&mut SqliteSnapshotControl<'_>)->Result<SqliteDatabase,String>{let mut p=Projection::new(Self::SQLITE_SCHEMA,control)?;let mut styles=BTreeMap::new();let mut parents=BTreeMap::new();for(ordinal,style)in self.styles.iter().enumerate(){p.check_rows(styles.len()+1)?;let id=number(ordinal+1)?;if styles.insert(style.id.as_str(),id).is_some(){return Err("duplicate document style identity".into());}}for(ordinal,style)in self.styles.iter().enumerate(){let parent=style.based_on.as_deref().map(|s|styles.get(s).copied().ok_or("dangling document style inheritance")).transpose()?;parents.insert(number(ordinal+1)?,parent);p.insert_key_float("semio_document_style",number(ordinal+1)?,&[Cell::Integer(1),Cell::Integer(number(ordinal)?),Cell::Text(&style.id),Cell::Text(&style.name),parent.map(Cell::Integer).unwrap_or(Cell::Null)])?;}let mut images=BTreeMap::new();for(ordinal,image)in self.images.iter().enumerate(){let id=p.insert_float("semio_document_image",&[Cell::Integer(1),Cell::Integer(number(ordinal)?),Cell::Text(&image.id),Cell::Text(&image.mime),Cell::Blob(&image.bytes)])?;if images.insert(image.id.as_str(),id).is_some(){return Err("duplicate document image identity".into());}}let root=project_block_collection(&self.blocks,DOCUMENT_TABLES,Some(&styles),Some(&images),&mut p)?;p.insert_key_float("semio_document_document",1,&[Cell::Text(&self.schema),Cell::Integer(root)])?;let db=p.finish()?;style_cycles(&parents,control)?;Ok(db)}
fn from_sqlite_database(db:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>)->Result<Self,String> { Self::reconstruct_sqlite_database(db, control, Self::SQLITE_SCHEMA) }
}

impl SemioDocumentSnapshot {
    /// 🧩️ Restores the owned typed subset inside its independently declared relational composition.
    pub fn reconstruct_sqlite_database(db:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>, declared_schema: &str)->Result<Self,String> {
control.check_database(db,SqliteSnapshotPhase::ReconstructSnapshot)?;validate_sqlite_database_schema(db,declared_schema,control.limits()).map_err(|e|e.to_string())?;let doc=single_float_row(db,"semio_document_document")?;identity(doc,3)?;if doc.rowid!=1{return Err("invalid document identity".into());}let style_rows=ordered_float_rows(db,"semio_document_style",2,control)?;let image_rows=ordered_float_rows(db,"semio_document_image",2,control)?;let mut styles=BTreeMap::new();let mut images=BTreeMap::new();let mut parents=BTreeMap::new();let mut names=BTreeSet::new();for row in &style_rows{identity(row,6)?;if row.integer(1)?!=1||!names.insert(row.text(3)?)||styles.insert(row.rowid,row.text(3)?).is_some(){return Err("invalid document style identity or owner".into());}parents.insert(row.rowid,optional_integer(*row,5)?);}style_cycles(&parents,control)?;let mut names=BTreeSet::new();for row in &image_rows{identity(row,6)?;if row.integer(1)?!=1||!names.insert(row.text(3)?)||images.insert(row.rowid,row.text(3)?).is_some(){return Err("invalid document image identity or owner".into());}}let mut blocks=reconstruct_block_collections(db,DOCUMENT_TABLES,&[doc.integer(2)?],Some(&styles),Some(&images),control)?;let mut r=Reconstruction::new(control)?;let mut native_styles=Vec::new();for row in style_rows{native_styles.push(DocStyle{id:r.text(row.text(3)?)?,name:r.text(row.text(4)?)?,based_on:restore_reference(row,5,Some(&styles),&mut r)?});}let mut native_images=Vec::new();for row in image_rows{native_images.push(DocImage{id:r.text(row.text(3)?)?,mime:r.text(row.text(4)?)?,bytes:r.blob(row.blob(5)?)?});}let result=Self{schema:r.text(doc.text(1)?)?,styles:native_styles,images:native_images,blocks:blocks.remove(0)};r.checkpoint()?;Ok(result)
    }
}

fn float_columns(table:&str)->&'static [FloatColumn]{match table{"semio_document_run"=>&[FloatColumn::Binary64(7)],"semio_document_image_block"=>&[FloatColumn::Binary64(3),FloatColumn::Binary64(4)],"semio_presentation_run"=>&[FloatColumn::Binary64(7)],"semio_presentation_image_block"=>&[FloatColumn::Binary64(3),FloatColumn::Binary64(4)],_=>&[]}}
trait FloatProjection { fn insert_float(&mut self,table:&str,cells:&[Cell<'_>])->Result<i64,String>; fn insert_key_float(&mut self,table:&str,key:i64,cells:&[Cell<'_>])->Result<(),String>; }
impl FloatProjection for Projection<'_,'_> { fn insert_float(&mut self,table:&str,cells:&[Cell<'_>])->Result<i64,String>{insert_ieee754(self,table,cells,float_columns(table))} fn insert_key_float(&mut self,table:&str,key:i64,cells:&[Cell<'_>])->Result<(),String>{insert_key_ieee754(self,table,key,cells,float_columns(table))} }
fn float_rows<'a>(db:&'a SqliteDatabase,table:&str,control:&mut SqliteSnapshotControl<'_>)->Result<Vec<SqliteRow<'a>>,String>{let table_rows=db.table(table)?;control.check_rows(table_rows.rows.len())?;control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,0,table_rows.rows.len())?;let mut result=Vec::new();for(count,row)in table_rows.rows.iter().enumerate(){result.push(SqliteRow::new(row,float_columns(table))?);if count%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,count,table_rows.rows.len())?;}}Ok(result)}
fn ordered_float_rows<'a>(db:&'a SqliteDatabase,table:&str,ordinal:usize,control:&mut SqliteSnapshotControl<'_>)->Result<Vec<SqliteRow<'a>>,String>{let mut result=Vec::new();for(count,row)in semio_framework_os_kernel::sqlite_snapshot::artifact::ordered_row_refs(db.table(table)?,ordinal,control)?.into_iter().enumerate(){result.push(SqliteRow::new(row,float_columns(table))?);if count%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,count,0)?;}}Ok(result)}
fn single_float_row<'a>(db:&'a SqliteDatabase,table:&str)->Result<SqliteRow<'a>,String>{SqliteRow::new(db.table(table)?.single_row()?,float_columns(table))}

impl SemioDocumentSnapshot{
/// 📏️ Bounds explicitly owned native fields before encoding.
pub fn native_fields(&self,b:&mut Bound<'_,'_>)->Result<(),String>{b.text(&self.schema)?;b.entities(self.styles.len())?;for style in &self.styles{b.text(&style.id)?;b.text(&style.name)?;b.optional_text(style.based_on.as_deref())?;}b.entities(self.images.len())?;for image in &self.images{b.text(&image.id)?;b.text(&image.mime)?;b.bytes(&image.bytes)?;}native_blocks(&self.blocks,b)?;Ok(())}
}

/// 📑️ Bounds actual shared DocBlock variants and their typed inline fields iteratively.
pub fn native_blocks(roots:&[DocBlock],b:&mut Bound<'_, '_>)->Result<(),String>{b.entities(roots.len())?;let mut pending:Vec<_>=roots.iter().rev().collect();while let Some(block)=pending.pop(){b.entities(1)?;match block{
DocBlock::Paragraph{style_id,runs}|DocBlock::Heading{style_id,runs,..}=>{b.scalars(1)?;b.optional_text(style_id.as_deref())?;b.entities(runs.len())?;for run in runs{b.text(&run.text)?;b.scalars(4)?;b.optional_text(run.style.font.as_deref())?;b.optional_text(run.style.color.as_deref())?;b.optional_text(run.style.link.as_deref())?;}},
DocBlock::List{items,..}=>{b.scalars(1)?;b.entities(items.len())?;for item in items.iter().rev(){b.entities(item.blocks.len())?;pending.extend(item.blocks.iter().rev());}},
DocBlock::Table{rows}=>{b.entities(rows.len())?;for row in rows.iter().rev(){b.entities(row.cells.len())?;for cell in row.cells.iter().rev(){b.entities(cell.blocks.len())?;pending.extend(cell.blocks.iter().rev());}}},
DocBlock::Code{language,text}=>{b.optional_text(language.as_deref())?;b.text(text)?;},DocBlock::Quote{blocks}=>{b.entities(blocks.len())?;pending.extend(blocks.iter().rev());},
DocBlock::Image{image_id,alt,..}=>{b.text(image_id)?;b.text(alt)?;b.scalars(2)?;},DocBlock::PageBreak=>{}}}Ok(())}
